async def finish_listener_worker(
    worker: asyncio.Task[None], stop: Callable[[], None] | None
) -> None:
    """Finish cancellation cleanup even if the caller is cancelled repeatedly."""

    async def cleanup() -> None:
        if stop is not None:
            try:
                await asyncio.to_thread(stop)
            except Exception:
                logging.getLogger(__name__).warning(
                    "Listener stop failed during cleanup"
                )
        # Cancellation wins over a simultaneous transport failure, but the
        # worker still has to finish before the caller releases ownership.
        await asyncio.gather(worker, return_exceptions=True)

    cleanup_task = asyncio.create_task(cleanup())
    while True:
        try:
            await asyncio.shield(cleanup_task)
            return
        except asyncio.CancelledError:
            if cleanup_task.cancelled():
                raise


